import React, { useEffect, useRef, useState } from "react";
import Ably from "ably";
import { useParams } from "react-router-dom";
import Hls from "hls.js";
import { supabase } from "./Login";

function Stream() {
  const [isStreamOffline, setIsStreamOffline] = useState(false);
  const [chatMessages, setChatMessages] = useState([]);
  const [newMessage, setNewMessage] = useState("");
  const { nick } = useParams();
  const videoRef = useRef(null);
  const hlsRef = useRef(null);
  const [desc, setDesc] = useState("");
  const [newDesc, setNewDesc] = useState(null);
  const [title, setTitle] = useState("");
  const [newTitle, setNewTitle] = useState(null);
  const [viewerCount, setViewerCount] = useState(null);
  const chatBoxRef = useRef(null);
  const ws = useRef(null);

  const userRole = document.cookie
    .split("; ")
    .find((row) => row.startsWith("role="))
    ?.split("=")[1];

  const userid = document.cookie
    .split("; ")
    .find((row) => row.startsWith("nick="))
    ?.split("=")[1];

  const userr = document.cookie
    .split("; ")
    .find((row) => row.startsWith("userid="))
    ?.split("=")[1];

    useEffect(() => {
      const connectWebSocket = () => {
        if (!ws.current) {
          ws.current = new WebSocket(
            `wss://fawe.online:3000/live/${nick}`
          );
        }
    
        ws.current.onopen = () => {
          console.log("WebSocket connected to stream:", nick);
        };
    
        ws.current.onmessage = (event) => {
          try {
            const data = JSON.parse(event.data);
    
            switch (data.type) {
              case "viewerCount":
                setViewerCount(data.count);
                break;
              case "chatMessage":
                setChatMessages((prev) => [...prev, data]);
                break;
              case "chatHistory":
                setChatMessages(data.messages || []);
                break;
              default:
                console.warn("Неизвестный тип WebSocket-сообщения:", data.type);
            }
          } catch (e) {
            console.error("Ошибка при обработке сообщения WebSocket:", e);
          }
        };
    
        ws.current.onerror = (err) => {
          console.error("WebSocket error:", err);
        };
      };
    
      connectWebSocket();
    }, [nick]);

  useEffect(() => {
    const checkStreamAvailability = async () => {
      try {
        const response = await fetch(
          `http://fawe.online:8080/live/${nick}.m3u8`
        );
        setIsStreamOffline(!response.ok);
      } catch (error) {
        setIsStreamOffline(true);
      }
    };

    checkStreamAvailability();
    const interval = setInterval(() => {
      checkStreamAvailability();
    }, 30000);

    return () => clearInterval(interval);
  }, [nick]);

  useEffect(() => {
    const fetchDescription = async () => {
      const { data: userData } = await supabase
        .from("Users")
        .select()
        .eq("Nick", nick);
      const { data, error } = await supabase
        .from("Description")
        .select()
        .eq("userid", userData[0]?.id);

      if (error) {
        console.error("Ошибка при загрузке описания:", error);
      } else {
        if (data.length > 0) {
          setDesc(data[0].desc);
          setTitle(data[0].name);
        } else {
          const { error: insertError } = await supabase
            .from("Description")
            .insert([{ userid: userData[0].id, desc: "", name: "" }]);
          if (insertError) {
            console.error("Ошибка при создании описания:", insertError);
          }
        }
      }
    };

    fetchDescription();
  }, [nick]);

  useEffect(() => {
    if (chatBoxRef.current) {
      chatBoxRef.current.scrollTop = chatBoxRef.current.scrollHeight;
    }
  }, [chatMessages]);

  const handleCanPlay = () => {
    if (videoRef.current) {
      videoRef.current.currentTime = videoRef.current.duration - 3.5;
    }
  };

  useEffect(() => {
    if (videoRef.current && !isStreamOffline && Hls.isSupported()) {
      const hls = new Hls();
      hlsRef.current = hls;
  
      hls.loadSource(`http://fawe.online:8080/live/${nick}.m3u8`);
      hls.attachMedia(videoRef.current);
  
      hls.on(Hls.Events.MANIFEST_PARSED, function () {
        console.log("HLS stream ready");
      });
  
      hls.on(Hls.Events.ERROR, function (event, data) {
        if (data.fatal) {
          switch (data.type) {
            case Hls.ErrorTypes.NETWORK_ERROR:
              console.warn("Network error, retrying...");
              hls.startLoad();
              break;
            case Hls.ErrorTypes.MEDIA_ERROR:
              console.warn("Media error, trying to recover...");
              hls.recoverMediaError();
              break;
            default:
              hls.destroy();
              setIsStreamOffline(true);
              break;
          }
        }
      });
  
      return () => {
        hls.destroy();
      };
    }
  
    if (isStreamOffline) {
      const retryTimeout = setTimeout(() => {
        setIsStreamOffline(false); 
      }, 5000);
  
      return () => clearTimeout(retryTimeout);
    }
  }, [isStreamOffline]);

  const sendMessage = () => {
    if (!userid || !userRole) {
      alert("Войдите в аккаунт");
      return;
    }
  
    if (newMessage.trim()) {
      const messagePayload = {
        type: "chatMessage",
        user: userid,
        nick: userid,
        role: nick === userid ? "Admin" : userRole,
        message: newMessage,
      };
  
      ws.current.send(JSON.stringify(messagePayload));
      setNewMessage("");
    }
  };

  const updatetitle = async () => {
    const { error } = await supabase
      .from("Description")
      .update({
        name: newTitle,
      })
      .eq("userid", userr);
    if (error) {
      alert("Ошибка");
      return;
    }
    setNewTitle(null);
    alert("Изменено название");
  };

  const updatedec = async () => {
    const { error } = await supabase
      .from("Description")
      .update({
        desc: newDesc,
      })
      .eq("userid", userr);
    if (error) {
      alert("Ошибка");
      return;
    }
    setNewDesc(null);
    alert("Изменено описание");
  };

  return (
    <div className="stream-container">
      <div className="video-section">
        <h2>🔥 {nick} Прямая трансляция</h2>
        <div className="player-container">
          {isStreamOffline ? (
            <div>Стрим оффлайн</div>
          ) : (
            <>
              <video
                ref={videoRef}
                width="100%"
                height="100%"
                controls
                autoPlay={true}
                onPlay={handleCanPlay}
                style={{
                  backgroundColor: "black",
                  borderRadius: "10px",
                  objectFit: "cover",
                  overflow: "hidden",
                }}
              >
                Ваш браузер не поддерживает HTML5 video.
              </video>
              <div id="viewer-count">
                👁 Зрителей: {viewerCount !== null ? viewerCount : "..."}
              </div>
            </>
          )}
        </div>

        <div className="stream-title">
          <h3>📺 Название трансляции</h3>
          {nick === userid ? (
            <>
              <input
                type="text"
                value={newTitle ?? title}
                onChange={(e) => setNewTitle(e.target.value)}
                placeholder="Введите название трансляции"
              />
              <button onClick={updatetitle}>Сохранить название</button>
            </>
          ) : (
            <p>{title || "Без названия."}</p>
          )}
        </div>

        <div className="stream-description">
          <h3>📝 Описание трансляции</h3>
          {nick === userid ? (
            <>
              <textarea
                value={newDesc === null ? desc : newDesc}
                onChange={(e) => setNewDesc(e.target.value)}
                rows={4}
                placeholder="Введите описание трансляции"
              />
              <button onClick={updatedec}>Сохранить описание</button>
            </>
          ) : (
            <p>{desc || "Описание отсутствует."}</p>
          )}
        </div>
      </div>

      <div className="chat-section">
        <h3>💬 Чат</h3>
        <div className="chat-box" ref={chatBoxRef}>
          {chatMessages.map((msg, index) => (
            <div key={index} className="chat-message">
              <span className="chat-user">
                {msg.role === "Admin" && (
                  <span className="admin-badge">(⌐■_■)</span>
                )}
                {msg.role === "Vip" && <span className="admin-badge">^_~</span>}
                {msg.nick}:
              </span>
              <span className="chat-text">{msg.message}</span>
            </div>
          ))}
        </div>
        <div style={{ display: "flex", flexDirection: "row" }}>
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") sendMessage();
            }}
            placeholder="Введите сообщение..."
          />
          <button onClick={sendMessage}>Отправить</button>
        </div>
      </div>
    </div>
  );
}

export default Stream;