import React, {useEffect, useState} from 'react';
import './App.css';
import { supabase } from './App';

const Header = () => {
  const [nick, setNick] = useState(null);
  const [userid, setUserId] = useState(null)

  const userRole = document.cookie
  .split("; ")
  .find((row) => row.startsWith("role="))
  ?.split("=")[1];

  useEffect(() => {
    const cookies = document.cookie
      .split("; ")
      .find((row) => row.startsWith("nick="));

    if (cookies) {
      const roleValue = cookies.split("=")[1];
      setNick(roleValue);
    }

    const cookiess = document.cookie
      .split("; ")
      .find((row) => row.startsWith("userid="));

    if (cookiess) {
      const roleValue = cookiess.split("=")[1];
      setUserId(roleValue);
    }
  }, []);

  const logout = () => {
    document.cookie = "userid=; path=/; max-age=0";
    document.cookie = "nick=; path=/; max-age=0";
    document.cookie = "role=; path=/; max-age=0";
    window.location.reload();
  }

  return (
    <header className="header">
      <nav className="nav">
        <ul className="nav-list">
          <li style={{width:"100%"}}>
            <button
              className={`nav-item login-button-header ${
                window.location.pathname === "/" ? "active" : ""
              }`}
              onClick={() => {
                window.location.href = "/";
              }}
            >
              Стримы
            </button>
          </li>
        </ul>
      </nav>
      {userid ? (
        <div className="login">
          <button
            className="login-button-header"
            onClick={() => {
              alert(`url трансляции: rtmp://www.fawe.online:1935/live\nКлюч трансляции: ${nick}`)
            }}
          >
            {nick}
          </button>
          <button className="login-button-header" onClick={logout}>
            Выйти
          </button>
        </div>
      ) : (
        <div className="login">
          <button
            className="login-button-header"
            onClick={() => {
              window.location.href = "/login";
            }}
          >
            Войти
          </button>
        </div>
      )}
    </header>
  );
};

export default Header;