import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./App.css";
import { supabase } from "./Login";
import bcrypt from 'bcryptjs'

function SignIn() {
  const [login, setLogin] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [nick, setNick]= useState("");
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!login || !password || !confirmPassword || !nick) {
      return;
    }

    const hasCyrillic = /[А-Яа-яЁё]/;
    const validPattern = /^[a-zA-Z0-9]+$/;

    if (hasCyrillic.test(login) || hasCyrillic.test(nick)) {
      alert("Логин и ник не должны содержать русские буквы");
      return;
    }

    if (!validPattern.test(login) || !validPattern.test(nick)) {
      alert(
        "Логин и ник могут содержать только латинские буквы, цифры, подчёркивания и точки"
      );
      return;
    }

    if (password !== confirmPassword) {
      alert("Пароли не совпадают");
      return;
    }

    try {
      const { data: dataid, error: rr } = await supabase.from("Users").select().order("id", { ascending: false }).limit(1);
      const hashpassword = await bcrypt.hash(password, 10);
      const { data, error } = await supabase.from("Users").insert({
        id: dataid[0].id+1,
        Login: login,
        Password: hashpassword,
        Role: "User",
        Nick: nick
      });
      if (error) {
        return;
      }
      document.cookie = `role=User; path=/; max-age=86400;`;
      document.cookie = `nick=${nick}; path=/; max-age=86400;`;
      document.cookie = `userid=${dataid[0].id+1}; path=/; max-age=86400;`;
      navigate("/");
      navigate(0);
    } catch (err) {}
  };

  return (
    <div className="auth-container">
      <div className="auth-box">
        <h2>Регистрация</h2>
        <form onSubmit={handleSubmit}>
          <div className="input-group">
            <label>Придумайте никнейм:</label>
            <input
              value={nick}
              onChange={(e) => setNick(e.target.value)}
              required
              onInvalid={(e) => e.target.setCustomValidity("Заполните поле")}
              onInput={(e) => e.target.setCustomValidity("")}
            />
          </div>
          <div className="input-group">
            <label>Логин:</label>
            <input
              value={login}
              onChange={(e) => setLogin(e.target.value)}
              required
              onInvalid={(e) => e.target.setCustomValidity("Заполните поле")}
              onInput={(e) => e.target.setCustomValidity("")}
            />
          </div>
          <div className="input-group">
            <label>Пароль:</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              onInvalid={(e) => e.target.setCustomValidity("Заполните поле")}
              onInput={(e) => e.target.setCustomValidity("")}
            />
          </div>
          <div className="input-group">
            <label>Подтверждение пароля:</label>
            <input
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              required
              onInvalid={(e) => e.target.setCustomValidity("Заполните поле")}
              onInput={(e) => e.target.setCustomValidity("")}
            />
          </div>
          <button type="submit">Зарегестрироваться</button>
        </form>
        <div className="switch-form">
          <p>Уже есть аккаунт?</p>
          <button onClick={() => navigate("/login")}>Войти</button>
        </div>
      </div>
    </div>
  );
}

export default SignIn;